1. SOURCE_CLAIM_JSON: {"title":"Department Press Briefing - January 11, 2022","publisher":"U.S. Department of State","publication_date":"2022-01-11","url":"https://2021-2025.state.gov/briefings/department-press-briefing-january-11-2022/","claim":"The State Department said the Strategic Stability Dialogue with Russia included preliminary ideas on military transparency, risk-reduction measures, and exercises, with diplomacy presented as the best option for restoring stability and security.","locator":"search result snippet; Strategic Stability Dialogue passage","source_type":"official","source_confidence":"high","source_confidence_reason":"Contemporaneous official briefing on active diplomacy and risk-reduction.","final_evidence_use":"final_evidence","period_fit":"Directly in 2022 and before the invasion became full-scale.","ruler_attribution":"Indirect but strong; this describes Biden administration diplomacy and restraint choices.","contrary_evidence":["It is a briefing summary, not a signed agreement.","No durable U.S.-Russia breakthrough is shown here."],"lenses":["2B.1","2B.7"]}

2. SOURCE_CLAIM_JSON: {"title":"Remarks in an Exchange With Reporters Prior to Departure for Lorain, Ohio","publisher":"The American Presidency Project","publication_date":"2022-02-17","url":"https://www.presidency.ucsb.edu/documents/remarks-exchange-with-reporters-prior-departure-for-lorain-ohio","claim":"Biden said the invasion threat was very high, but also said there was still a clear diplomatic path and that the way through the crisis was 'by diplomacy.'","locator":"lines 65-100","source_type":"official","source_confidence":"high","source_confidence_reason":"Direct presidential transcript with exact quotes.","final_evidence_use":"final_evidence","period_fit":"Immediately before the February 2022 invasion.","ruler_attribution":"Direct Biden statement.","contrary_evidence":["He also said he expected the invasion within days.","This shows intent to avoid war, not proof that diplomacy would succeed."],"lenses":["2B.1","2B.3","2B.6","2B.7"]}

3. SOURCE_CLAIM_JSON: {"title":"Remarks on Russia's Actions in Ukraine","publisher":"The American Presidency Project","publication_date":"2022-02-22","url":"https://www.presidency.ucsb.edu/documents/remarks-russias-actions-ukraine","claim":"Biden said Russia had begun carving out Ukrainian territory, that Moscow was setting up a rationale to take more territory by force, and that the United States and allies remained open to serious diplomacy.","locator":"lines 94-101","source_type":"official","source_confidence":"high","source_confidence_reason":"Direct presidential transcript with explicit policy and threat language.","final_evidence_use":"final_evidence","period_fit":"Two days before the full invasion.","ruler_attribution":"Direct Biden statement.","contrary_evidence":["The speech also warned of sanctions and escalation.","It is still a prewar statement, not wartime conduct."],"lenses":["2B.1","2B.3","2B.6","2B.7","2B.10"]}

4. SOURCE_CLAIM_JSON: {"title":"Joint Statement by the North Atlantic Treaty Organization Heads of State and Government on Russia's Attack on Ukraine","publisher":"The American Presidency Project","publication_date":"2022-02-25","url":"https://www.presidency.ucsb.edu/documents/joint-statement-the-north-atlantic-treaty-organization-heads-state-and-government-russias","claim":"The NATO leaders, including Biden, condemned Russia's full-scale invasion as brutal and unprovoked, called for withdrawal, pledged support to Ukraine, and described allied measures as preventive, proportionate, and non-escalatory.","locator":"lines 62-70","source_type":"official","source_confidence":"high","source_confidence_reason":"Primary allied statement with explicit wording on legality, restraint, and support.","final_evidence_use":"final_evidence","period_fit":"Immediate response to the invasion in 2022.","ruler_attribution":"Indirect but strong; this is Biden’s NATO response architecture.","contrary_evidence":["It is collective allied policy, not Biden acting alone.","Support for Ukraine can still prolong a war even when lawful."],"lenses":["2B.1","2B.4","2B.7","2B.10"]}

